contract InvMutTest {
    C c;

    constructor() { c = new C(address(new __InvMutHandleStub())); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function testRequestPriceRevertsForNonAsserter(bytes32 identifier, uint256 time, bytes memory ancillaryData) public {
        require(address(c) != address(this), "test contract must not be the asserter");
        require(address(c) != msg.sender, "caller must not be the asserter");

        bool reverted;
        c.requestPrice(identifier, time, ancillaryData); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted);
    }
}

